    # find bar: row or column that is one color throughout, color != 0, longest
    H,W=len(grid),len(grid[0])
    best=None
    for i,row in enumerate(grid):
        c=row[0]
        if c!=0 and all(v==c for v in row): best=('h',i,c) if best is None or W>=H else best
    for j in range(W):
